calcular_vif <- function(df) {
  sapply(names(df), function(variable) {
    otros <- setdiff(names(df), variable)
    if (!length(otros)) return(1)
    ajuste <- lm(reformulate(otros, response = variable), data = df)
    1 / (1 - summary(ajuste)$r.squared)
  })
}
